package com.wiseway.service;
import com.wiseway.api.ApiDtos.*; import com.wiseway.domain.*; import java.util.*; import org.springframework.stereotype.Service;
@Service public class RecommendationService {
 private final LocationService locations; private final RouteDataService routes; private final FareCalculationService fares;
 public RecommendationService(LocationService l,RouteDataService r,FareCalculationService f){locations=l;routes=r;fares=f;}
 public CompareResponse compare(CompareRequest r,Set<String> excluded){var from=locations.resolve(r.origin());var to=locations.resolve(r.destination());if(from.isEmpty()||to.isEmpty())return empty("UNKNOWN_LOCATION","Both locations must be selected from WiseWay's supported demo locations; no route was fabricated.");var route=routes.find(from.get().id(),to.get().id());if(route.isEmpty())return empty("ROUTE_UNAVAILABLE","No curated road route is configured for this location pair. Try a supported demo route.");var c=r.constraints();var options=new ArrayList<TransportOption>();for(var mode:TransportMode.values()){var fare=fares.calculate(mode,route.get().roadDistanceMetres());if(fare.amount()!=null&&(mode==TransportMode.AUTO||mode==TransportMode.CAB||mode==TransportMode.BUS||route.get().verifiedTransitModes().contains(mode.name())))options.add(new TransportOption(mode.name().toLowerCase()+"-route",mode,Math.max(1,route.get().roadDurationSeconds()/60)+(mode==TransportMode.BUS?8:0),fare.amount(),"INR",mode==TransportMode.BUS?1:0,mode==TransportMode.CAB?1:4,"Route-specific estimate for "+from.get().name()+" → "+to.get().name()+"."));}var result=RecommendationEngine.recommend(options,r.preference()==null?PreferenceProfile.BALANCED:r.preference(),new RecommendationEngine.Constraints(c==null?null:c.maxFare(),r.departureAt(),c==null?null:c.arriveBy()),excluded);return new CompareResponse("CURATED_ROUTE_ESTIMATES","Road distance and duration come from local curated demo route data. Fares are formula-based estimates; public transport availability is only verified for listed modes.",result.feasible().stream().map(x->toOption(x,route.get().roadDistanceMetres(),route.get().verifiedTransitModes())).toList(),result.infeasible().stream().map(x->new OptionResponse(x.option().id(),x.option().mode(),x.option().durationMinutes(),x.option().estimatedFare(),x.option().currency(),x.option().transfers(),x.option().walkingMinutes(),x.option().description(),null,List.of(),x.reasons(),route.get().verifiedTransitModes().contains(x.option().mode().name())?"AVAILABLE":"ESTIMATED_ONLY","CALCULATED_ESTIMATE","WiseWay local route data")).toList(),result.noFit(),result.message());}
 public PlanBResponse planB(PlanBRequest r){var compare=compare(new CompareRequest(r.origin(),r.destination(),r.departureAt(),r.preference(),r.constraints()),new HashSet<>(Optional.ofNullable(r.excludeOptionIds()).orElse(List.of())));return new PlanBResponse(r.scenario(),compare.dataQuality(),"Simulated Plan B; not a live disruption alert.",compare.feasibleOptions().isEmpty()?null:compare.feasibleOptions().get(0),compare.feasibleOptions().size()>1?compare.feasibleOptions().subList(1,compare.feasibleOptions().size()):List.of(),compare.noFeasibleOption(),compare.message());}
 private OptionResponse toOption(RecommendationEngine.RankedOption x,int metres,Set<String> verified){return new OptionResponse(x.option().id(),x.option().mode(),x.option().durationMinutes(),x.option().estimatedFare(),x.option().currency(),x.option().transfers(),x.option().walkingMinutes(),x.option().description(),x.score(),x.reasons(),List.of(),verified.contains(x.option().mode().name())?"AVAILABLE":"ESTIMATED_ONLY","CALCULATED_ESTIMATE","WiseWay local route data · "+metres+"m road route");}
 private CompareResponse empty(String quality,String message){return new CompareResponse(quality,message,List.of(),List.of(),true,message);}
}
